CREATE TABLE `work_logs` (
  `id` varchar(36) NOT NULL,
  `organization_id` varchar(36) NOT NULL,
  `author_id` varchar(36) NOT NULL,
  `business_date` date NOT NULL,
  `body` text NOT NULL,
  `task_id` varchar(36) DEFAULT NULL,
  `row_version` bigint NOT NULL DEFAULT '1',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `organization_id` (`organization_id`,`task_id`),
  KEY `idx_logs_author` (`organization_id`,`author_id`,`business_date`),
  CONSTRAINT `work_logs_ibfk_1` FOREIGN KEY (`organization_id`, `author_id`) REFERENCES `users` (`organization_id`, `id`),
  CONSTRAINT `work_logs_ibfk_2` FOREIGN KEY (`organization_id`, `task_id`) REFERENCES `tasks` (`organization_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
